#include "ResultListScene.hpp"
#include <cstdio>
namespace th075 {
u16 ResultListScene::advance(const MenuInput& input,u32 count,ResultListSignals& signals){signals.render_result_list();signals.present_result_list();i8 v=0,h=0;for(auto n:input.vertical)if(n==1)v=1;for(auto n:input.vertical)if(n==-1)v=-1;for(auto n:input.horizontal)if(n==1)h=1;for(auto n:input.horizontal)if(n==-1)h=-1;
 if(v){signals.sound(39);if(cardsMode){page=i16(page+v);if(page<0)page=i16((count-1)/10);else if(page>i32((count-1)/10))page=0;}else difficulty=u8((i32(difficulty)+v+4)%4);signals.update_result_text(cardsMode);}
 if(h){signals.sound(39);if(h<0){character=u8(i8(character)-1);if(i8(character)<0)character=9;for(i8 i=9;i>=6;i--)if(character==u8(i)&&!unlocks.character_available(i,false))character=u8(character-1);}else {character=u8(character+1);for(u8 i=6;i<=9;i++)if(character==i&&!unlocks.character_available(i8(i),false))character=u8(character+1);if(character>9)character=0;}signals.load_result_character(character);if(cardsMode)page=0;signals.update_result_text(cardsMode);}
 if(alpha!=255)alpha=u8(alpha+25);if(input.confirm[0]==1||input.confirm[1]==1){if(!cardsMode){signals.update_result_text(true);page=0;cardsMode=true;signals.sound(45);}else{signals.sound(45);cardsMode=false;signals.update_result_text(false);}}if(input.escape||input.cancel[0]==1||input.cancel[1]==1){signals.sound(40);return 0x2202;}return 14;
}
std::string ResultListScene::text(const GameProfile& profile,const CardList& list)const{const auto& p=profile.characters[character].difficulty[cardsMode?0:difficulty];std::string result;char line[256];if(cardsMode){for(u32 i=u32(page)*10;i<u32(page)*10+10&&i<list.names.size()&&i<150;i++){const auto& card=p.cards[i];std::string name;if(card.attempts)name=list.names[i];else for(int q=0;q<16;q++){name.push_back(char(0x81));name.push_back(char(0x48));}std::snprintf(line,sizeof(line)," No.%03d  %-59s %03d/%03d",int(i+1),name.c_str(),card.attempts?int(card.captures):0,card.attempts?int(card.attempts):0);result+=line;result+=char(92);result+='n';}}else for(auto n:p.counters){std::snprintf(line,sizeof(line),"%5d",i32(n));result+=line;result+=char(92);result+='n';}return result;}
}
